package main

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// notGenerated is the skip of a tree with no generated file.
func notGenerated(string) bool { return false }

// goCoveredMissed: the lines of the blocks the tests never ran are kept,
// in order, once each, and a block run by either listing is not missed.
func TestGoCoveredKeepsTheLinesNotRun(t *testing.T) {
	t.Parallel()
	files, err := goCovered("mode: set\n" +
		"m/a.go:9.1,10.2 1 0\nm/a.go:3.1,4.2 2 0\nm/a.go:3.1,4.2 2 0\n" +
		"m/a.go:6.1,7.2 1 1\nm/a.go:12.1,13.2 1 0\nm/a.go:12.1,13.2 1 1\n" +
		"m/b.go:1.1,2.2 0 0\n")
	if err != nil {
		t.Fatal(err)
	}
	byPath := map[string]covered{}
	for _, file := range files {
		byPath[file.path] = file
	}
	if got := byPath["m/a.go"].missed; !slices.Equal(got, []int{3, 9}) {
		t.Errorf("missed in a.go: %v", got)
	}
	if got := byPath["m/b.go"].missed; len(got) != 0 {
		t.Errorf("a block with no statements is not missed: %v", got)
	}
}

// the package is named with its percentage and its first three missed
// lines, file then line.
func TestBelowFloorNamesThePackageAndItsFirstLines(t *testing.T) {
	t.Parallel()
	files := []covered{
		{path: "a/x.go", count: 10, ran: 5, missed: []int{12, 3, 9, 7}},
		{path: "a/y.go", count: 10, ran: 10},
		{path: "b/z.go", count: 4, ran: 4},
	}
	got := belowFloor(files, 80, nil, notGenerated)
	if len(got) != 1 || got[0].pkg != "a" || got[0].percent != 75 {
		t.Fatalf("under: %+v", got)
	}
	want := []string{"a/x.go:3", "a/x.go:7", "a/x.go:9"}
	if !slices.Equal(got[0].missed, want) {
		t.Errorf("first lines: %v, want %v", got[0].missed, want)
	}
}

// a package exactly at the floor passes; one just under does not; the
// failures come in package order.
func TestBelowFloorPassesTheFloorItself(t *testing.T) {
	t.Parallel()
	files := []covered{
		{path: "z/f.go", count: 4, ran: 3},
		{path: "a/f.go", count: 4, ran: 2},
		{path: "m/f.go", count: 4, ran: 4},
	}
	got := belowFloor(files, 75, nil, notGenerated)
	if len(got) != 1 || got[0].pkg != "a" {
		t.Errorf("at 75: %+v", got)
	}
	got = belowFloor(files, 76, nil, notGenerated)
	if len(got) != 2 || got[0].pkg != "a" || got[1].pkg != "z" {
		t.Errorf("at 76: %+v", got)
	}
}

// anti-test: a generated file under the floor does not fail the package.
func TestBelowFloorSkipsGeneratedFiles(t *testing.T) {
	t.Parallel()
	files := []covered{
		{path: "a/x.go", count: 4, ran: 4},
		{path: "a/mock_test_gen.go", count: 40, ran: 0},
	}
	generated := func(path string) bool { return path == "a/mock_test_gen.go" }
	if got := belowFloor(files, 100, nil, generated); len(got) != 0 {
		t.Errorf("a generated file failed the package: %+v", got)
	}
	if got := belowFloor(files, 100, nil, notGenerated); len(got) != 1 {
		t.Errorf("the same file, not generated: %+v", got)
	}
}

// anti-test: a package with no statements does not fail, and neither does
// one whose only statements are in generated files.
func TestBelowFloorSkipsPackagesWithNoStatements(t *testing.T) {
	t.Parallel()
	files := []covered{
		{path: "empty/types.go", count: 0, ran: 0},
		{path: "gen/g.go", count: 5, ran: 0},
	}
	generated := func(path string) bool { return path == "gen/g.go" }
	if got := belowFloor(files, 100, nil, generated); len(got) != 0 {
		t.Errorf("no statements: %+v", got)
	}
}

// a file allowed with a reason is left out of its package's share.
func TestBelowFloorLeavesAllowedFilesOut(t *testing.T) {
	t.Parallel()
	files := []covered{
		{path: "a/x.go", count: 4, ran: 4},
		{path: "a/tty.go", count: 8, ran: 0, missed: []int{1}},
	}
	allowed := map[string]string{"a/tty.go": "needs a terminal"}
	if got := belowFloor(files, 100, allowed, notGenerated); len(got) != 0 {
		t.Errorf("an allowed file counted: %+v", got)
	}
	if got := belowFloor(files, 100, nil, notGenerated); len(got) != 1 {
		t.Errorf("the same file, not allowed: %+v", got)
	}
}

// a file is generated by the header the go tool reads: a line before the
// package clause that begins "// Code generated", ends "DO NOT EDIT.".
func TestGeneratedFileReadsTheStandardHeader(t *testing.T) {
	t.Parallel()
	dir := tree(t, map[string]string{
		"gen.go": "// Code generated by mockgen. DO NOT EDIT.\n\npackage a\n",
		"late.go": "package a\n\n// Code generated by hand. DO NOT EDIT.\n" +
			"var x int\n",
		"plain.go": "// Package a does things.\npackage a\n",
		"near.go":  "// Code generated by mockgen, edit freely.\npackage a\n",
		"empty.go": "// nothing else\n",
	})
	if generatedFile(dir, "empty.go") {
		t.Errorf("a file with no package clause is generated")
	}
	_, perr := goCovered("mode: set\nm/a.go:x.1,2.2 1 0\n")
	if perr != nil {
		t.Fatal(perr)
	}
	if got := startLine("x.1,2.2"); got != 0 {
		t.Errorf("a span with no line: %d", got)
	}
	for name, want := range map[string]bool{"gen.go": true,
		"late.go": false, "plain.go": false, "near.go": false,
		"missing.go": false} {
		if got := generatedFile(dir, name); got != want {
			t.Errorf("%s: generated %v, want %v", name, got, want)
		}
	}
}

// goMod is a module's go.mod.
const goMod = "module example.com/m\n\ngo 1.27\n"

// profileWriter is a runner that answers go test by writing the profile
// it was asked for, and says every call it was given.
type profileWriter struct {
	profile string
	calls   *[]string
}

// run is the runner.
func (writer profileWriter) run(dir, name string, args ...string) (string, error) {
	*writer.calls = append(*writer.calls, name+" "+strings.Join(args, " "))
	if name == "go" && slices.Contains(args, "-coverprofile="+goProfile) {
		path := filepath.Join(dir, goProfile)
		if err := os.WriteFile(path, []byte(writer.profile), 0o600); err != nil {
			return "", err
		}
	}
	return "", nil
}

// a gate tree: a package a with a file half run, a generated file in it
// unrun, and a package b run whole.
func gateTree(t *testing.T) string {
	t.Helper()
	return tree(t, map[string]string{
		"go.mod": goMod,
		"a/x.go": "package a\n",
		"a/gen.go": "// Code generated by mockgen. DO NOT EDIT.\n\n" +
			"package a\n",
		"b/z.go": "package b\n",
	})
}

// gateProfile is the profile of gateTree.
const gateProfile = "mode: set\n" +
	"example.com/m/a/x.go:3.1,4.2 2 1\n" +
	"example.com/m/a/x.go:6.1,7.2 2 0\n" +
	"example.com/m/a/gen.go:3.1,9.2 20 0\n" +
	"example.com/m/b/z.go:3.1,4.2 3 1\n"

// the gate fails a package under the floor, names it, its percentage and
// its first uncovered line as the module-relative file:line, and does not
// count the generated file.
func TestCoverGateFailsAPackageUnderTheFloor(t *testing.T) {
	t.Parallel()
	dir := gateTree(t)
	var calls []string
	var out bytes.Buffer
	cfg := gamed(t, "cover 60")
	err := coverGate(dir, cfg, profileWriter{gateProfile, &calls}.run, &out)
	if !errors.Is(err, errUnderFloor) {
		t.Fatalf("under the floor: %v", err)
	}
	for _, want := range []string{"a: 50.0% is under the floor of 60%",
		"a/x.go:6"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("%q is not in\n%s", want, out.String())
		}
	}
	if strings.Contains(out.String(), "gen.go") ||
		strings.Contains(out.String(), "b:") {
		t.Errorf("said what it should not:\n%s", out.String())
	}
	// a package a hair under the floor is not shown as being on it.
	hair := "mode: set\nexample.com/m/a/x.go:3.1,4.2 9999 1\n" +
		"example.com/m/a/x.go:6.1,7.2 1 0\n"
	out.Reset()
	if err := coverGate(dir, gamed(t, "cover 100"),
		profileWriter{hair, &calls}.run, &out); err == nil ||
		!strings.Contains(out.String(), "a: 99.9% is under the floor of 100%") {
		t.Errorf("a hair under: %v\n%s", err, out.String())
	}
	cfg = gamed(t, "cover 50")
	out.Reset()
	if err := coverGate(dir, cfg, profileWriter{gateProfile, &calls}.run,
		&out); err != nil {
		t.Errorf("at the floor: %v", err)
	}
}

// anti-test: with no cover line anywhere, there is no gate: nothing is
// run and nothing is said.
func TestCoverGateWithNoFloorRunsNothing(t *testing.T) {
	t.Parallel()
	dir := gateTree(t)
	var calls []string
	var out bytes.Buffer
	cfg := dotted(t, "author x")
	if err := coverGate(dir, cfg, profileWriter{gateProfile, &calls}.run,
		&out); err != nil || len(calls) != 0 || out.Len() != 0 {
		t.Errorf("no floor: %v, ran %v, said %q", err, calls, out.String())
	}
}

// every allowed file and its reason is said on every run, floor or not,
// and a file that was allowed but is not in the profile is said so.
func TestCoverGateSaysEveryAllowedFile(t *testing.T) {
	t.Parallel()
	dir := gateTree(t)
	var calls []string
	cfg := gamed(t, "cover 100", "cover allow a/x.go the second block is a panic",
		"cover allow nowhere.go a mistake")
	var out bytes.Buffer
	err := coverGate(dir, cfg, profileWriter{gateProfile, &calls}.run, &out)
	if err != nil {
		t.Errorf("a/x.go allowed: %v", err)
	}
	for _, want := range []string{
		"cover allow a/x.go: the second block is a panic\n",
		"cover allow nowhere.go: a mistake (no such file in the profile)\n"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("%q is not in\n%s", want, out.String())
		}
	}
	out.Reset()
	calls = nil
	cfg = gamed(t, "cover allow a/x.go because")
	if err := coverGate(dir, cfg, profileWriter{gateProfile, &calls}.run,
		&out); err != nil || len(calls) != 0 ||
		!strings.Contains(out.String(), "cover allow a/x.go: because") {
		t.Errorf("an allow and no floor: %v, ran %v, said %q", err, calls,
			out.String())
	}
}

// the gate's errors: tests that fail, and a profile it cannot read.
func TestCoverGateRefusesWhatItCannotMeasure(t *testing.T) {
	t.Parallel()
	dir := gateTree(t)
	var calls []string
	cfg := gamed(t, "cover 10")
	err := coverGate(dir, cfg, profileWriter{"mode: set\nbroken\n", &calls}.run,
		&bytes.Buffer{})
	if !errors.Is(err, errProfile) {
		t.Errorf("a broken profile: %v", err)
	}
	failing := func(string, string, ...string) (string, error) {
		return "", os.ErrPermission
	}
	if err := coverGate(dir, cfg, failing, &bytes.Buffer{}); !errors.Is(err,
		os.ErrPermission) {
		t.Errorf("tests that fail: %v", err)
	}
	// a module with no module line: files are named as the profile has them
	bare := tree(t, map[string]string{"go.mod": "go 1.27\n"})
	profile := "mode: set\nplain/f.go:1.1,2.2 2 0\n"
	var out bytes.Buffer
	err = coverGate(bare, cfg, profileWriter{profile, &calls}.run, &out)
	if !errors.Is(err, errUnderFloor) || !strings.Contains(out.String(),
		"plain: 0.0%") {
		t.Errorf("a module with no name: %v\n%s", err, out.String())
	}
}

// check runs the gate after the tests and fails on it; with the tests
// failing first, it never measures.
func TestCheckRunsTheGateAfterTheTests(t *testing.T) {
	t.Parallel()
	dir := gateTree(t)
	var calls []string
	var out bytes.Buffer
	cfg := gamed(t, "cover 90")
	err := check(repoAt(dir), cfg, profileWriter{gateProfile, &calls}.run, &out)
	if !errors.Is(err, errUnderFloor) {
		t.Fatalf("check under the floor: %v", err)
	}
	last := calls[len(calls)-1]
	if !strings.Contains(last, "-coverprofile") {
		t.Errorf("the gate was not the last call: %v", calls)
	}
	calls = nil
	out.Reset()
	passing := gamed(t, "name x")
	if err := check(repoAt(dir), passing, profileWriter{gateProfile, &calls}.run,
		&out); err != nil {
		t.Errorf("check with no floor: %v", err)
	}
	for _, call := range calls {
		if strings.Contains(call, "-coverprofile") {
			t.Errorf("measured with no floor: %v", calls)
		}
	}
}
